 <div class="split"><form class="panel form-panel" method="post" action="?page=interviews&action=session_save"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="submission_token" value="<?=e($sessionCreateToken)?>"><div class="form-title"><h2>创建面试场次</h2></div><label>招聘岗位<select name="post_id"><?php foreach($posts as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></label><label>面试日期<input type="date" name="interview_date" value="<?=date('Y-m-d',strtotime('+1 day'))?>" required></label><label>时间范围<input name="time_range" value="14:00-16:00" required></label><label>面试地点<input name="location" value="第一会议室" required></label><button class="btn primary">创建场次</button></form>
