if($page==='interview_results'){
 admin_header('面试结果','interview_results');page_head('人才管理 / 面试汇总','面试结果','按面试官权重汇总，所有面试官提交后形成最终面试分。','<a class="btn secondary" href="?page=interview_results&action=export_interviews">导出面试结果</a>');
 $rows=$pdo->query("SELECT ic.id,c.name,p.name post_name,s.interview_date,s.location,(SELECT COUNT(*) FROM session_interviewer x WHERE x.session_id=s.id) need,(SELECT COUNT(*) FROM interview_score x WHERE x.interview_candidate_id=ic.id) done,(SELECT ROUND(SUM(COALESCE(sc.total_score,(sc.suzhi_score+sc.postq_score)/40.0)*si.weight)/NULLIF(SUM(si.weight),0),2) FROM interview_score sc JOIN session_interviewer si ON si.id=sc.interviewer_id WHERE sc.interview_candidate_id=ic.id) overall FROM interview_candidate ic JOIN candidate c ON c.id=ic.candidate_id JOIN interview_session s ON s.id=ic.session_id JOIN post p ON p.id=s.post_id ORDER BY s.interview_date DESC,ic.seq")->fetchAll();
 $details=$pdo->query("SELECT sc.id,c.name,u.real_name,COALESCE(sc.total_score,(sc.suzhi_score+sc.postq_score)/40.0) total_score,sc.strengths,sc.risks,sc.recommendation,sc.submitted_at FROM interview_score sc JOIN interview_candidate ic ON ic.id=sc.interview_candidate_id JOIN candidate c ON c.id=ic.candidate_id JOIN session_interviewer si ON si.id=sc.interviewer_id JOIN user u ON u.id=si.user_id ORDER BY sc.id DESC")->fetchAll();
 ?><div class="panel table-wrap"><table><thead><tr><th>候选人</th><th>岗位 / 场次</th><th>评分进度</th><th>固定表加权总分</th><th>建议等级</th><th>状态</th></tr></thead><tbody><?php foreach($rows as $r):$complete=(int)$r['need']>0&&(int)$r['done']>=(int)$r['need'];$level=$r['overall']>=4?'强烈推荐':($r['overall']>=3.5?'推荐录用':($r['overall']>=3?'待定 / 复试':'不推荐'));?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['post_name'])?><small><?=e($r['interview_date'].' · '.$r['location'])?></small></td><td><?=$r['done']?> / <?=$r['need']?></td><td><strong class="result-score"><?=$complete?number_format((float)$r['overall'],2).' / 5':'—'?></strong></td><td><?=$complete?e($level):'—'?></td><td><?=status_badge($complete?'done':'pending')?></td></tr><?php endforeach;?></tbody></table></div>
 <div class="panel table-wrap section-gap"><div class="panel-head"><div><h2>面试官评分明细</h2><small>使用固定七维评分表；误提交可重置后重新填写</small></div></div><table><thead><tr><th>候选人</th><th>面试官</th><th>加权总分</th><th>录用建议</th><th>优势与亮点</th><th>不足与风险</th><th>提交时间</th><th>操作</th></tr></thead><tbody><?php foreach($details as $d):$recommendation=['strong'=>'强烈推荐录用','recommend'=>'推荐录用','pending'=>'待定 / 需要复试','reject'=>'不推荐录用'][$d['recommendation']]??'历史评分';?><tr><td><b><?=e($d['name'])?></b></td><td><?=e($d['real_name'])?></td><td><strong><?=number_format((float)$d['total_score'],2)?> / 5</strong></td><td><?=e($recommendation)?></td><td><?=e($d['strengths']??'—')?></td><td><?=e($d['risks']??'—')?></td><td><?=e($d['submitted_at'])?></td><td><form method="post" action="?page=interview_results&action=score_reset" data-confirm-message="确认重置这条面试评分？"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="score_id" value="<?=$d['id']?>"><button class="table-action danger-text">重置</button></form></td></tr><?php endforeach;?></tbody></table></div><?php admin_footer();exit;
