function standard_dimension_meta(): array {
 $dimensions=['age'=>['name'=>'年龄','category'=>'basic_info'],'health'=>['name'=>'健康状况','category'=>'basic_info'],'edu'=>['name'=>'学历','category'=>'exp_qualification'],'school'=>['name'=>'毕业院校','category'=>'exp_qualification'],'major'=>['name'=>'专业','category'=>'exp_qualification'],'title'=>['name'=>'职称','category'=>'exp_qualification'],'politics'=>['name'=>'政治面貌','category'=>'exp_qualification'],'work_years'=>['name'=>'参加工作年限','category'=>'work_history'],'prof_years'=>['name'=>'从事专业年限','category'=>'work_history'],'group_co'=>['name'=>'集团公司','category'=>'work_history'],'listed_co'=>['name'=>'上市公司','category'=>'work_history'],'private_co'=>['name'=>'非上市公司','category'=>'work_history'],'work_bg'=>['name'=>'工作背景','category'=>'work_history'],'computer'=>['name'=>'计算机基本操作','category'=>'skills'],'language'=>['name'=>'外语','category'=>'skills']];
 foreach(db()->query("SELECT dim_code,MAX(dim_name) dim_name FROM scoring_standard WHERE category='basic_quality' AND status!='retired' GROUP BY dim_code") as $row)$dimensions[$row['dim_code']]=['name'=>$row['dim_name'],'category'=>'basic_quality'];
 return $dimensions;
}
function standard_rule_text(string $type,string $json): string {$rule=json_decode($json,true)?:[];$value=(string)($rule['value']??'');if($type==='eq'&&preg_match('/^(\d+(?:\.\d+)?)至(\d+(?:\.\d+)?)(?:岁|年)?.*$/u',$value,$m))return '数值区间：'.$m[1].' ≤ X ＜ '.$m[2];if($type==='range'||$type==='bool_range'){if(isset($rule['min'],$rule['max']))$text='数值区间：'.$rule['min'].' ≤ X ＜ '.$rule['max'];elseif(isset($rule['max']))$text='数值区间：X ＜ '.$rule['max'];elseif(isset($rule['min']))$text='数值区间：X ≥ '.$rule['min'];else $text='未设置范围';return $type==='bool_range'&&isset($rule['is_mgmt'])?$text.((int)$rule['is_mgmt']?'，高管':'，非高管'):$text;}if($type==='in')return '属于：'.implode('、',(array)($rule['values']??[]));return '等于：'.$value;}
function score_bar(string $label,float $score):string{$max=$label==='综合测评'?50:(in_array($label,['基本素质','专业能力'],true)?25:100);$display=$label==='综合测评'?'基本条件':$label;$raw=max(0,min(100,$max>0?$score/$max*100:0));$width=$raw;return '<div class="score-bar"><span>'.$display.'<small>原始得分比例 '.number_format($raw,1).'%</small></span><i><b style="width:'.$width.'%"></b></i><strong>折算 '.number_format($score,1).' / '.$max.'</strong>'.render_module_score_items($label,$max).'</div>';}
function render_module_score_items(string $label,float $moduleMax): string {global $selected;if(empty($selected['answer_id']))return '';$pdo=db();$rows=[];$totalRawMax=0;if($label==='综合测评'){$st=$pdo->prepare('SELECT dim_code,dim_name,matched_tier,score FROM eval_score_detail WHERE answer_id=? ORDER BY id');$st->execute([(int)$selected['answer_id']]);$rows=$st->fetchAll();$maxSt=$pdo->prepare("SELECT dim_code,MAX(tier_value) max_score FROM scoring_standard WHERE version=? AND status='published' AND category!='basic_quality' GROUP BY dim_code");$maxSt->execute([(int)$selected['standard_version']]);$maxBy=[];foreach($maxSt->fetchAll() as $row)$maxBy[$row['dim_code']]=(float)$row['max_score'];foreach($rows as &$row){$row['stem_snapshot']=$row['dim_name'];$row['max_score']=$maxBy[$row['dim_code']]??0;$row['note']=$row['matched_tier']??'';$totalRawMax+=(float)$row['max_score'];}unset($row);}else{$type=$label==='基本素质'?'base':'post';$st=$pdo->prepare('SELECT stem_snapshot,score,max_score,score_status FROM answer_detail WHERE answer_id=? AND question_type=? ORDER BY id');$st->execute([(int)$selected['answer_id'],$type]);$rows=$st->fetchAll();foreach($rows as $row)$totalRawMax+=(float)$row['max_score'];}if(!$rows)return '<details class="score-items"><summary>暂无逐题得分</summary></details>';$html='<details class="score-items"><summary>查看每题原始与折算得分</summary><ul>';foreach($rows as $row){$raw=(float)$row['score'];$rawMax=(float)$row['max_score'];$converted=$totalRawMax>0?$raw/$totalRawMax*$moduleMax:0;$note=$row['note']??'';$html.='<li><b>'.e((string)$row['stem_snapshot']).'</b>'.($note!==''?'<small>'.e((string)$note).'</small>':'').'<span>原始 '.$raw.' / '.$rawMax.'　→　折算 '.number_format($converted,1).' / '.$moduleMax.'</span></li>';}$html.='</ul></details>';return $html;}
function recalc_result(int $answerId): void {
 $pdo=db();$st=$pdo->prepare("SELECT question_type,SUM(score) got,SUM(max_score) max_score,SUM(CASE WHEN score_status='manual_pending' THEN 1 ELSE 0 END) pending FROM answer_detail WHERE answer_id=? GROUP BY question_type");$st->execute([$answerId]);$groups=[];$pending=0;foreach($st->fetchAll() as $g){$groups[$g['question_type']]=(float)$g['max_score']>0?round((float)$g['got']/(float)$g['max_score']*25,1):0;$pending+=(int)$g['pending'];}$suzhi=$groups['base']??0;$postq=$groups['post']??0;$old=$pdo->prepare('SELECT eval_score FROM result WHERE answer_id=?');$old->execute([$answerId]);$eval=(float)$old->fetchColumn();$total=$pending?0:round($eval+$suzhi+$postq,1);$weights=json_encode(['basic_conditions'=>50,'basic_quality'=>25,'professional'=>25],JSON_UNESCAPED_UNICODE);$pdo->prepare('UPDATE result SET suzhi_score=?,postq_score=?,total_score=?,weight_snapshot=?,score_status=? WHERE answer_id=?')->execute([$suzhi,$postq,$total,$weights,$pending?'manual_pending':'completed',$answerId]);
}
